void harness_PI_set_parameter_value
      (const asn1SccOBCP_Parameter_Id *IN_id,
       const asn1SccOBCP_Parameter_Value *IN_parameter_value)

{
   int empty = -1;
   for (int i = 0; i < PARAM_STORE_SIZE; i++) {
      if (param_store[i].valid && param_store[i].id == *IN_id) {
         param_store[i].value = *IN_parameter_value;
         return;
      }
      if (!param_store[i].valid && empty < 0) {
         empty = i;
      }
   }
   if (empty >= 0) {
      param_store[empty].id    = *IN_id;
      param_store[empty].value = *IN_parameter_value;
      param_store[empty].valid = true;
   }
}


/* -----------------------------------------------------------------------
 * Harness OBCP definitions
 * ----------------------------------------------------------------------- */

typedef struct {
   asn1SccOBCP_Id   id;
   const char      *src;
} Harness_ObcpDef;

/* IO write test OBCP: exercises the obcpio.write function by sending
 * plain text, numeric conversions and string concatenation to the output.
 */
static const Harness_ObcpDef OBCP_IOTEST = {
   .id  = {'I','O','T','S','T'},
   .src =
      "import obcpio\n"
      "obcpio.write('IO test: single-line write\\n')\n"
      "obcpio.write('IO test: numeric value: ' + str(42) + '\\n')\n"
      "obcpio.write('IO test: ' + 'string ' + 'concatenation\\n')\n"
};

/* Datapool test OBCP: exercises write and read of int, enum, float and bool
 * parameters using the MicroPython obcpdatapool module.  Parameter IDs:
 *   1 = integer   2 = enum   3 = float   4 = bool
 */
static const Harness_ObcpDef OBCP_DPTEST = {
   .id  = {'D','P','T','S','T'},
   .src =
      "import obcpdatapool\n"
      "import obcpio\n"
      "obcpdatapool.writeintparameter(1, -42)\n"
      "v = obcpdatapool.readintparameter(1)\n"
      "if v != -42: raise RuntimeError('int fail')\n"
      "obcpio.write('DP int OK: ' + str(v) + '\\n')\n"
      "obcpdatapool.writeenumparameter(2, 7)\n"
      "v = obcpdatapool.readenumparameter(2)\n"
      "if v != 7: raise RuntimeError('enum fail')\n"
      "obcpio.write('DP enum OK: ' + str(v) + '\\n')\n"
      "obcpdatapool.writefloatparameter(3, 2.718)\n"
      "v = obcpdatapool.readfloatparameter(3)\n"
      "obcpio.write('DP float OK: ' + str(v) + '\\n')\n"
      "obcpdatapool.writeboolparameter(4, True)\n"
      "v = obcpdatapool.readboolparameter(4)\n"
      "if not v: raise RuntimeError('bool fail')\n"
      "obcpio.write('DP bool OK: ' + str(v) + '\\n')\n"
};

/* Events test OBCP: sends a known sequence of events via obcpevents.sendevent.
 * The harness verifies that all three events arrive in the expected order.
 * Event IDs: 101, 202, 303
 */
static const Harness_ObcpDef OBCP_EVTEST = {
   .id  = {'E','V','T','S','T'},
   .src =
      "import obcpevents\n"
      "obcpevents.sendevent(101)\n"
      "obcpevents.sendevent(202)\n"
      "obcpevents.sendevent(303)\n"
};

static const Harness_ObcpDef OBCP_TEST1 = {
   .id  = {'T','E','S','T','1'},
   .src = "import obcptime\nobcptime.wait(3000)\n"
};

static const Harness_ObcpDef OBCP_TEST2 = {
   .id  = {'T','E','S','T','2'},
   .src = "import obcptime\nobcptime.wait(5000)\n"
};

static const Harness_ObcpDef OBCP_TEST3 = {
   .id  = {'T','E','S','T','3'},
   .src = "import obcptime\nobcptime.wait(3000)\n"
};

/* Gettime test OBCP: records the time before and after a known wait period,
 * stores the elapsed milliseconds and a pass/fail flag in the datapool.
 * Parameter IDs: 10 = elapsed milliseconds (int), 11 = passed (int: 1=pass)
 * Tolerance window: ±200 ms around the nominal 2000 ms wait.
 */
#define TIMETEST_WAIT_MS       2000
#define TIMETEST_TOLERANCE_MS   200
#define TIMETEST_ELAPSED_PARAM_ID  10
#define TIMETEST_PASSED_PARAM_ID   11

static const Harness_ObcpDef OBCP_TIMETEST = {
   .id  = {'T','I','M','E','T'},
   .src =
      "import obcptime\n"
      "import obcpdatapool\n"
      "import obcpio\n"
      "t0 = obcptime.gettime()\n"
      "obcptime.wait(2000)\n"
      "t1 = obcptime.gettime()\n"
      "elapsed = (t1[0] - t0[0]) * 1000 + (t1[1] - t0[1])\n"
      "obcpdatapool.writeintparameter(10, elapsed)\n"
      "passed = 1 if 1800 <= elapsed <= 2200 else 0\n"
      "obcpdatapool.writeintparameter(11, passed)\n"
      "obcpio.write('Gettime test: elapsed=' + str(elapsed) + 'ms, passed=' + str(passed) + '\\n')\n"
};

/* -----------------------------------------------------------------------
 * Helpers
 * ----------------------------------------------------------------------- */

static bool load_obcp(const Harness_ObcpDef *def)
{
   asn1SccOBCP_Code code;
   const size_t len = strlen(def->src) + 1;
   memcpy(code.arr, def->src, len);
   code.nCount = (int)len;

   asn1SccT_Boolean ok = FALSE;
   harness_RI_load_obcp(&def->id, &code, &ok);
   if (!ok) {
      printf("Could not load OBCP %.5s\n", def->id);
   }
   return (bool)ok;
}

static bool activate_obcp(const Harness_ObcpDef *def)
{
   asn1SccT_Boolean ok = FALSE;
   harness_RI_activate_obcp(&def->id, &ok);
   if (!ok) {
      printf("Could not activate OBCP %.5s\n", def->id);
   }
   return (bool)ok;
}

static asn1SccOBCP_Execution_Status get_status(const Harness_ObcpDef *def)
{
   asn1SccOBCP_Execution_Status status = OBCP_Execution_Status_inactive;
   asn1SccT_Boolean ok = FALSE;
   harness_RI_get_obcp_status(&def->id, &status, &ok);
   if (!ok) {
      printf("Could not get status for OBCP %.5s\n", def->id);
   }
   return status;
}

/* -----------------------------------------------------------------------
 * Trigger state machine
 * ----------------------------------------------------------------------- */

typedef enum {
   PHASE_INIT,
   PHASE_IO_WRITE_TEST,
   PHASE_DATAPOOL_TEST,
   PHASE_EVENTS_TEST,
   PHASE_CONCURRENCY_WAIT_TEST1,
   PHASE_CONCURRENCY_ALL_RUNNING,
   PHASE_GETTIME_TEST,
} Harness_Phase;

void harness_PI_trigger(void)
{
   static Harness_Phase phase = PHASE_INIT;

   switch (phase) {

      /* -----------------------------------------------------------------
       * Start the engine and kick off the IO write test OBCP.
       * ----------------------------------------------------------------- */
      case PHASE_INIT: {
         harness_RI_start_obcp_engine();

         if (!load_obcp(&OBCP_IOTEST)) return;
         if (!activate_obcp(&OBCP_IOTEST)) return;

         printf("IO write test OBCP activated\n");
         io_write_test_active = true;
         io_test_msg_index = 0;
         phase = PHASE_IO_WRITE_TEST;
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the IO write test OBCP to complete, then kick off the
       * datapool test OBCP.
       * ----------------------------------------------------------------- */
      case PHASE_IO_WRITE_TEST: {
         const asn1SccOBCP_Execution_Status sio = get_status(&OBCP_IOTEST);

         if (sio == OBCP_Execution_Status_inactive) {
            io_write_test_active = false;
            if (io_test_msg_index != IO_TEST_EXPECTED_COUNT) {
               printf("IO test ERROR: expected %zu messages, received %zu\n",
                      IO_TEST_EXPECTED_COUNT, io_test_msg_index);
            } else {
               printf("IO write tests finished — all %zu messages verified OK\n",
                      IO_TEST_EXPECTED_COUNT);
            }

            if (!load_obcp(&OBCP_DPTEST)) return;
            if (!activate_obcp(&OBCP_DPTEST)) return;

            printf("Datapool test OBCP activated\n");
            phase = PHASE_DATAPOOL_TEST;
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the datapool test OBCP to complete, then launch the
       * concurrency tests (TEST1 and TEST2 run in parallel).
       * ----------------------------------------------------------------- */
      case PHASE_DATAPOOL_TEST: {
         const asn1SccOBCP_Execution_Status sdp = get_status(&OBCP_DPTEST);

         if (sdp == OBCP_Execution_Status_inactive) {
            printf("Datapool tests finished\n");

            if (!load_obcp(&OBCP_EVTEST)) return;
            if (!activate_obcp(&OBCP_EVTEST)) return;

            printf("Events test OBCP activated\n");
            events_test_active         = true;
            events_test_received_count = 0;
            events_test_all_ok         = true;
            phase = PHASE_EVENTS_TEST;
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the events test OBCP to complete, then verify that all
       * expected events were received, and launch the concurrency tests.
       * ----------------------------------------------------------------- */
      case PHASE_EVENTS_TEST: {
         const asn1SccOBCP_Execution_Status sev = get_status(&OBCP_EVTEST);

         if (sev == OBCP_Execution_Status_inactive) {
            events_test_active = false;

            if (!events_test_all_ok ||
                events_test_received_count != EVENTS_TEST_EXPECTED_COUNT)
            {
               printf("Events test FAILED: expected %zu events, received %zu%s\n",
                      EVENTS_TEST_EXPECTED_COUNT,
                      events_test_received_count,
                      events_test_all_ok ? "" : " (order/ID mismatch)");
            } else {
               printf("Events test PASSED: all %zu events received in correct order\n",
                      EVENTS_TEST_EXPECTED_COUNT);
            }

            if (!load_obcp(&OBCP_TEST1)) return;
            if (!load_obcp(&OBCP_TEST2)) return;
            if (!load_obcp(&OBCP_TEST3)) return;

            /* TEST1 and TEST2 start immediately; TEST3 waits for TEST1 */
            if (!activate_obcp(&OBCP_TEST1)) return;
            if (!activate_obcp(&OBCP_TEST2)) return;

            printf("TEST1 (3 s) and TEST2 (5 s) activated\n");
            phase = PHASE_CONCURRENCY_WAIT_TEST1;
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for TEST1 to complete, then activate TEST3 to exercise
       * concurrent execution of two active OBCPs.
       * ----------------------------------------------------------------- */
      case PHASE_CONCURRENCY_WAIT_TEST1: {
         const asn1SccOBCP_Execution_Status s1 = get_status(&OBCP_TEST1);

         printf("Status — TEST1: %d  TEST2: %d\n",
                s1, get_status(&OBCP_TEST2));

         if (s1 == OBCP_Execution_Status_inactive) {
            printf("TEST1 finished — activating TEST3 (3 s)\n");
            if (!activate_obcp(&OBCP_TEST3)) return;
            phase = PHASE_CONCURRENCY_ALL_RUNNING;
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for both remaining OBCPs to finish, then kick off the
       * gettime accuracy test.
       * ----------------------------------------------------------------- */
      case PHASE_CONCURRENCY_ALL_RUNNING: {
         const asn1SccOBCP_Execution_Status s2 = get_status(&OBCP_TEST2);
         const asn1SccOBCP_Execution_Status s3 = get_status(&OBCP_TEST3);

         printf("Status — TEST2: %d  TEST3: %d\n", s2, s3);

         if (s2 == OBCP_Execution_Status_inactive &&
             s3 == OBCP_Execution_Status_inactive)
         {
            printf("Concurrency tests finished\n");

            if (!load_obcp(&OBCP_TIMETEST)) return;
            if (!activate_obcp(&OBCP_TIMETEST)) return;

            printf("Gettime test OBCP activated (waiting %d ms)\n",
                   TIMETEST_WAIT_MS);
            phase = PHASE_GETTIME_TEST;
         }
         break;
      }

      /* -----------------------------------------------------------------
       * Wait for the gettime test OBCP to complete, then read the
       * elapsed time and pass/fail flag from the datapool and report.
       * ----------------------------------------------------------------- */
      case PHASE_GETTIME_TEST: {
         const asn1SccOBCP_Execution_Status st = get_status(&OBCP_TIMETEST);

         if (st == OBCP_Execution_Status_inactive) {
            /* Read results written by the OBCP into the datapool */
            const asn1SccOBCP_Parameter_Id elapsed_id = TIMETEST_ELAPSED_PARAM_ID;
            const asn1SccOBCP_Parameter_Id passed_id  = TIMETEST_PASSED_PARAM_ID;
            const asn1SccOBCP_Parameter_Type int_type  = OBCP_Parameter_Type_integer_type;
            asn1SccOBCP_Parameter_Value elapsed_val, passed_val;

            harness_PI_get_parameter_value(&elapsed_id, &int_type, &elapsed_val);
            harness_PI_get_parameter_value(&passed_id,  &int_type, &passed_val);

            const int32_t elapsed_ms = elapsed_val.u.int_value;
            const int32_t passed     = passed_val.u.int_value;

            if (passed) {
               printf("Gettime test PASSED: elapsed=%d ms "
                      "(nominal=%d ms, tolerance=\u00b1%d ms)\n",
                      elapsed_ms, TIMETEST_WAIT_MS, TIMETEST_TOLERANCE_MS);
            } else {
               printf("Gettime test FAILED: elapsed=%d ms "
                      "(expected %d\u00b1%d ms)\n",
                      elapsed_ms, TIMETEST_WAIT_MS, TIMETEST_TOLERANCE_MS);
            }

            printf("All tests finished — exiting\n");
            kill(getpid(), SIGTERM);
         }
         break;
      }
   }
}


